17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.springframework.http.HttpHeaders;
23	import org.springframework.http.HttpStatus;
24	import org.springframework.http.ResponseEntity;
25	import org.springframework.samples.petclinic.mapper.OwnerMapper;
26	import org.springframework.samples.petclinic.mapper.PetMapper;
27	import org.springframework.samples.petclinic.mapper.VisitMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.model.Pet;
30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.api.OwnersApi;
32	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
33	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
34	import org.springframework.samples.petclinic.rest.dto.PetDto;
35	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.VisitDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
38	import org.springframework.samples.petclinic.service.ClinicService;
39	import org.springframework.security.access.prepost.PreAuthorize;
40	import org.springframework.web.bind.annotation.CrossOrigin;
41	import org.springframework.web.bind.annotation.RequestMapping;
42	import org.springframework.web.bind.annotation.RestController;
43	import org.springframework.web.util.UriComponentsBuilder;
44	
45	import jakarta.transaction.Transactional;
46	
47	/**
48	 * @author Vitaliy Fedoriv
49	 */
50	
51	@RestController
52	@CrossOrigin(exposedHeaders = "errors, content-type")
53	@RequestMapping("/api")
54	public class OwnerRestControllerV1 implements OwnersApi {
55	
56	    private final ClinicService clinicService;
57	
58	    private final OwnerMapper ownerMapper;
59	
60	    private final PetMapper petMapper;
61	
62	    private final VisitMapper visitMapper;
63	
64	    public OwnerRestControllerV1(ClinicService clinicService,
65	                                 OwnerMapper ownerMapper,
66	                                 PetMapper petMapper,
67	                                 VisitMapper visitMapper) {
68	        this.clinicService = clinicService;
69	        this.ownerMapper = ownerMapper;
70	        this.petMapper = petMapper;
71	        this.visitMapper = visitMapper;
72	    }
73	
74	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
75	    @Override
76	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
77	        Collection<Owner> owners;
78	        if (lastName != null) {
79	            owners = this.clinicService.findOwnerByLastName(lastName);
80	        } else {
81	            owners = this.clinicService.findAllOwners();
82	        }
83	        if (owners.isEmpty()) {
84	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
85	        }
86	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
87	    }
88	
89	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
90	    @Override
91	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
92	        Owner owner = this.clinicService.findOwnerById(ownerId);
93	        if (owner == null) {
94	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
95	        }
96	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
97	    }
98	
99	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
100	    @Override
101	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
102	        HttpHeaders headers = new HttpHeaders();
103	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
104	        owner.setCity(resolveCity(owner.getCity()));
105	        owner.setMembershipNumber(this.clinicService.findAllOwners().size() + 1);
106	        owner.setCustomerCode(buildCustomerCode(owner.getCity()));
107	        owner.setMembershipTier(resolveMembershipTier());
108	        owner.setNamesakeCount(countNamesakes(owner.getLastName()));
109	        owner.setSharesHousehold(sharesHousehold(owner.getAddress(), owner.getCity()));
110	        this.clinicService.saveOwner(owner);
111	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
112	        headers.setLocation(UriComponentsBuilder.newInstance()
113	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
114	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
115	    }
116	
117	    /**
118	     * Resolve the city for a newly created owner. If an owner already exists in
119	     * that city (matched case-insensitively), reuse that owner's exact spelling;
120	     * otherwise the supplied city is title-cased.
121	     */
122	    private String resolveCity(String city) {
123	        if (city == null) {
124	            return null;
125	        }
126	        return this.clinicService.findAllOwners().stream()
127	            .map(Owner::getCity)
128	            .filter(existing -> existing != null && existing.equalsIgnoreCase(city))
129	            .findFirst()
130	            .orElseGet(() -> titleCase(city));
131	    }
132	
133	    /**
134	     * Title-case a city name: the first letter of each whitespace-separated word
135	     * is upper-cased and the remaining letters lower-cased.
136	     */
137	    private String titleCase(String city) {
138	        StringBuilder sb = new StringBuilder(city.length());
139	        boolean startOfWord = true;
140	        for (int i = 0; i < city.length(); i++) {
141	            char c = city.charAt(i);
142	            if (Character.isWhitespace(c)) {
143	                startOfWord = true;
144	                sb.append(c);
145	            } else if (startOfWord) {
146	                sb.append(Character.toUpperCase(c));
147	                startOfWord = false;
148	            } else {
149	                sb.append(Character.toLowerCase(c));
150	            }
151	        }
152	        return sb.toString();
153	    }
154	
155	    /**
156	     * The number of owners that, once created, are granted the 'FOUNDING'
157	     * membership tier. Owners created after this threshold receive 'STANDARD'.
158	     */
159	    private static final int FOUNDING_MEMBERSHIP_LIMIT = 100;
160	
161	    /**
162	     * Resolve the membership tier for a newly created owner: the first
163	     * {@link #FOUNDING_MEMBERSHIP_LIMIT} owners ever created are 'FOUNDING' and
164	     * all later owners are 'STANDARD'.
165	     */
166	    private String resolveMembershipTier() {
167	        long existingOwners = this.clinicService.findAllOwners().size();
168	        return existingOwners < FOUNDING_MEMBERSHIP_LIMIT ? "FOUNDING" : "STANDARD";
169	    }
170	
171	    /**
172	     * Build the customer code for a newly created owner, formatted as
173	     * '<UPPERCASE_CITY>-<NNNN>' where NNNN is one more than the number of owners
174	     * that already exist in that city, zero-padded to four digits.
175	     */
176	    private String buildCustomerCode(String city) {
177	        long ownersInCity = this.clinicService.findAllOwners().stream()
178	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
179	            .count();
180	        return String.format("%s-%04d", city.toUpperCase(), ownersInCity + 1);
181	    }
182	
183	    /**
184	     * Count how many owners already exist that share the given last name
185	     * (compared case-insensitively) at the moment a new owner is created.
186	     */
187	    private int countNamesakes(String lastName) {
188	        if (lastName == null) {
189	            return 0;
190	        }
191	        return (int) this.clinicService.findAllOwners().stream()
192	            .filter(existing -> existing.getLastName() != null
193	                && existing.getLastName().equalsIgnoreCase(lastName))
194	            .count();
195	    }
196	
197	    /**
198	     * Determine whether another owner already shares a household with a newly
199	     * created owner, i.e. an existing owner already has the same address and city
200	     * (both compared case-insensitively) at the moment the new owner is created.
201	     */
202	    private boolean sharesHousehold(String address, String city) {
203	        if (address == null || city == null) {
204	            return false;
205	        }
206	        return this.clinicService.findAllOwners().stream()
207	            .anyMatch(existing -> address.equalsIgnoreCase(existing.getAddress())
208	                && city.equalsIgnoreCase(existing.getCity()));
209	    }
210	
211	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
212	    @Override
213	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
214	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
215	        if (currentOwner == null) {
216	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
217	        }
218	        currentOwner.setAddress(ownerFieldsDto.getAddress());
219	        currentOwner.setCity(ownerFieldsDto.getCity());
220	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
221	        currentOwner.setLastName(ownerFieldsDto.getLastName());
222	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
223	        currentOwner.setEmail(ownerFieldsDto.getEmail());
224	        this.clinicService.saveOwner(currentOwner);
225	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
226	    }
227	
228	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
229	    @Transactional
230	    @Override
231	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
232	        Owner owner = this.clinicService.findOwnerById(ownerId);
233	        if (owner == null) {
234	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
235	        }
236	        this.clinicService.deleteOwner(owner);
237	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
238	    }
239	
240	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
241	    @Override
242	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
243	        Owner owner = this.clinicService.findOwnerById(ownerId);
244	        if (owner == null) {
245	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
246	        }
247	        HttpHeaders headers = new HttpHeaders();
248	        Pet pet = petMapper.toPet(petFieldsDto);
249	        owner.setId(ownerId);
250	        pet.setOwner(owner);
251	        pet.getType().setName(null);
252	        this.clinicService.savePet(pet);
253	        PetDto petDto = petMapper.toPetDto(pet);
254	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
255	            .buildAndExpand(pet.getId()).toUri());
256	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
257	    }
258	
259	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
260	    @Override
261	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
262	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
263	        if (currentOwner != null) {
264	            Pet currentPet = this.clinicService.findPetById(petId);
265	            if (currentPet != null) {
266	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
267	                currentPet.setName(petFieldsDto.getName());
268	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
269	                this.clinicService.savePet(currentPet);
270	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
271	            }
272	        }
273	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
274	    }
275	
276	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
277	    @Override
278	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
279	        HttpHeaders headers = new HttpHeaders();
280	        Visit visit = visitMapper.toVisit(visitFieldsDto);
281	        Pet pet = new Pet();
282	        pet.setId(petId);
283	        visit.setPet(pet);
284	        this.clinicService.saveVisit(visit);
285	        VisitDto visitDto = visitMapper.toVisitDto(visit);
286	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
287	            .buildAndExpand(visit.getId()).toUri());
288	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
289	    }
290	
291	
292	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
293	    @Override
294	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
295	        Owner owner = this.clinicService.findOwnerById(ownerId);
296	        if (owner != null) {
297	            Pet pet = owner.getPet(petId);
298	            if (pet != null) {
299	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
300	            }
301	        }
302	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
303	    }
304	}
