16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.Digits;
22	import jakarta.validation.constraints.Email;
23	import jakarta.validation.constraints.NotEmpty;
24	import jakarta.validation.constraints.Pattern;
25	
26	import java.time.LocalDate;
27	import java.util.*;
28	
29	/**
30	 * Simple JavaBean domain object representing an owner.
31	 *
32	 * @author Ken Krebs
33	 * @author Juergen Hoeller
34	 * @author Sam Brannen
35	 * @author Michael Isvy
36	 */
37	@Entity
38	@Table(name = "owners")
39	public class Owner extends Person {
40	    @Column(name = "address")
41	    @NotEmpty
42	    private String address;
43	
44	    @Column(name = "city")
45	    @NotEmpty
46	    private String city;
47	
48	    @Column(name = "telephone")
49	    @NotEmpty
50	    @Digits(fraction = 0, integer = 10)
51	    @Pattern(regexp = "^[0-9]{10}$", message = "Phone number must be exactly 10 digits")
52	    private String telephone;
53	
54	    @Column(name = "email")
55	    @Email
56	    private String email;
57	
58	    @Column(name = "registration_date")
59	    private LocalDate registrationDate;
60	
61	    @Column(name = "membership_number")
62	    private Integer membershipNumber;
63	
64	    @Column(name = "customer_code")
65	    private String customerCode;
66	
67	    @Column(name = "membership_tier")
68	    private String membershipTier;
69	
70	    @Column(name = "namesake_count")
71	    private Integer namesakeCount;
72	
73	    @Column(name = "shares_household")
74	    private Boolean sharesHousehold;
75	
76	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
77	    private Set<Pet> pets;
78	
79	    public String getAddress() {
80	        return this.address;
81	    }
82	
83	    public void setAddress(String address) {
84	        this.address = address;
85	    }
86	
87	    public String getCity() {
88	        return this.city;
89	    }
90	
91	    public void setCity(String city) {
92	        this.city = city;
93	    }
94	
95	    public String getTelephone() {
96	        return this.telephone;
97	    }
98	
99	    public void setTelephone(String telephone) {
100	        // Store telephone numbers as digits only, stripping spaces, dashes and
101	        // parentheses so that formatted input such as "(613) 555-0100" is kept
102	        // and compared as "6135550100".
103	        this.telephone = telephone == null ? null : telephone.replaceAll("[\\s()-]", "");
104	    }
105	
106	    public String getEmail() {
107	        return this.email;
108	    }
109	
110	    public void setEmail(String email) {
111	        this.email = email;
112	    }
113	
114	    public LocalDate getRegistrationDate() {
115	        return this.registrationDate;
116	    }
117	
118	    public void setRegistrationDate(LocalDate registrationDate) {
119	        this.registrationDate = registrationDate;
120	    }
121	
122	    public Integer getMembershipNumber() {
123	        return this.membershipNumber;
124	    }
125	
126	    public void setMembershipNumber(Integer membershipNumber) {
127	        this.membershipNumber = membershipNumber;
128	    }
129	
130	    public String getCustomerCode() {
131	        return this.customerCode;
132	    }
133	
134	    public void setCustomerCode(String customerCode) {
135	        this.customerCode = customerCode;
136	    }
137	
138	    public String getMembershipTier() {
139	        return this.membershipTier;
140	    }
141	
142	    public void setMembershipTier(String membershipTier) {
143	        this.membershipTier = membershipTier;
144	    }
145	
146	    public Integer getNamesakeCount() {
147	        return this.namesakeCount;
148	    }
149	
150	    public void setNamesakeCount(Integer namesakeCount) {
151	        this.namesakeCount = namesakeCount;
152	    }
153	
154	    public Boolean getSharesHousehold() {
155	        return this.sharesHousehold;
156	    }
157	
158	    public void setSharesHousehold(Boolean sharesHousehold) {
159	        this.sharesHousehold = sharesHousehold;
160	    }
161	
162	    protected Set<Pet> getPetsInternal() {
163	        if (this.pets == null) {
164	            this.pets = new HashSet<>();
165	        }
166	        return this.pets;
167	    }
168	
169	    protected void setPetsInternal(Set<Pet> pets) {
170	        this.pets = pets;
171	    }
172	
173	    public List<Pet> getPets() {
174	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
175	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
176	        return Collections.unmodifiableList(sortedPets);
177	    }
178	
179	    public void setPets(List<Pet> pets) {
180	        this.pets = new HashSet<>(pets);
181	    }
182	
183	    public void addPet(Pet pet) {
184	        getPetsInternal().add(pet);
185	        pet.setOwner(this);
186	    }
187	
188	    /**
189	     * Return the Pet with the given name, or null if none found for this Owner.
190	     *
191	     * @param name to test
192	     * @return true if pet name is already in use
193	     */
194	    public Pet getPet(String name) {
195	        return getPet(name, false);
196	    }
197	
198	    /**
199	     * Return the Pet with the given name, or null if none found for this Owner.
200	     *
201	     * @param name to test
202	     * @return true if pet name is already in use
203	     */
204	    public Pet getPet(String name, boolean ignoreNew) {
205	        name = name.toLowerCase();
206	        for (Pet pet : getPetsInternal()) {
207	            if (!ignoreNew || !pet.isNew()) {
208	                String compName = pet.getName();
209	                compName = compName.toLowerCase();
210	                if (compName.equals(name)) {
211	                    return pet;
212	                }
213	            }
214	        }
215	        return null;
216	    }
217	
218	    public Pet getPet(Integer petId) {
219	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
220	    }
221	
222	    @Override
223	    public String toString() {
224	        return new ToStringCreator(this)
225	
226	            .append("id", this.getId())
227	            .append("new", this.isNew())
228	            .append("lastName", this.getLastName())
229	            .append("firstName", this.getFirstName())
230	            .append("address", this.address)
231	            .append("city", this.city)
232	            .append("telephone", this.telephone)
233	            .toString();
234	    }
235	}
